import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {copilotAgentPlaneAppBuilder} from './config/app-builder'

import {agentsRoute} from './routes/agents-route'
import {Agents} from './routes/Agents'

import {subagentsRoute} from './routes/subagents-route'
import {Subagents} from './routes/Subagents'

import {sessionsRoute} from './routes/sessions-route'
import {Sessions} from './routes/Sessions'

export const copilotAgentPlaneApp = copilotAgentPlaneAppBuilder.createDataRouterAppFromRoutes([
  agentsRoute.toRoute({Component: Agents}),
  subagentsRoute.toRoute({Component: Subagents}),
  sessionsRoute.toRoute({Component: Sessions}),
])
registerDataRouterApp(copilotAgentPlaneApp)
