import {AlertIcon, CheckCircleFillIcon, CodeIcon, PackageIcon, ShieldLockIcon} from '@primer/octicons-react'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {Label, Stack} from '@primer/react'
import type {EnterpriseManagedClientSettings} from '../routes/agents-route'

type SettingsJson = Record<string, unknown> & {
  enabledPlugins?: Record<string, boolean>
  permissions?: {
    disableBypassPermissionsMode?: string
  }
}

function getPluginsCount(settings?: Record<string, unknown>): number {
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion -- narrows the untyped settings record for property access
  const s = settings as SettingsJson | undefined
  return Object.values(s?.enabledPlugins ?? {}).filter(Boolean).length
}

function getStatusColorClass(enabled: boolean): string {
  return enabled ? 'color-fg-success' : 'color-fg-muted'
}

interface ConfigurationSummaryProps {
  settings: EnterpriseManagedClientSettings
  customAgentsCount: number
}

export function ConfigurationSummary({settings, customAgentsCount}: ConfigurationSummaryProps) {
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion -- narrows the untyped settings record for property access
  const settingsJson = settings.settings as SettingsJson | undefined
  const pluginsCount = getPluginsCount(settingsJson)
  const showBypassPermissionsModeTile = isFeatureEnabled('agent_plane_disable_bypass_permissions_mode_tile')
  const disableBypassPermissionsMode = settingsJson?.permissions?.disableBypassPermissionsMode === 'disable'

  return (
    <Stack gap="normal">
      <div>
        <h3 className="h4">Configuration summary</h3>
        <p className="fgColor-muted text-small m-0">From {settings.display_name_with_owner}</p>
      </div>
      <div className="border rounded-2">
        <div className="d-flex flex-items-center flex-justify-between p-3">
          <div className="d-flex flex-items-center gap-2">
            <PackageIcon size={16} className="fgColor-muted" aria-hidden="true" />
            <span className="text-bold">Plugins</span>
            <Label variant="success">Preview</Label>
          </div>
          <div className={`d-flex flex-items-center gap-2 ${getStatusColorClass(pluginsCount > 0)}`}>
            <CheckCircleFillIcon size={16} aria-hidden="true" />
            <span>{pluginsCount} enabled</span>
          </div>
        </div>
        <div className="d-flex flex-items-center flex-justify-between p-3 border-top">
          <div className="d-flex flex-items-center gap-2">
            <CodeIcon size={16} className="fgColor-muted" aria-hidden="true" />
            <span className="text-bold">Custom agents</span>
          </div>
          <div className={`d-flex flex-items-center gap-2 ${getStatusColorClass(customAgentsCount > 0)}`}>
            <CheckCircleFillIcon size={16} aria-hidden="true" />
            <span>{customAgentsCount} enabled</span>
          </div>
        </div>
        {showBypassPermissionsModeTile && (
          <div className="d-flex flex-items-center flex-justify-between p-3 border-top">
            <div className="d-flex flex-items-center gap-2">
              <ShieldLockIcon size={16} className="fgColor-muted" aria-hidden="true" />
              <span className="text-bold">Bypass permissions mode</span>
              <Label variant="success">Preview</Label>
            </div>
            <div
              className={`d-flex flex-items-center gap-2 ${getStatusColorClass(disableBypassPermissionsMode)}`}
              data-testid="permissions-mode-status"
            >
              {disableBypassPermissionsMode ? (
                <>
                  <CheckCircleFillIcon size={16} aria-hidden="true" data-testid="permissions-mode-status-icon-check" />
                  <span>bypass disabled</span>
                </>
              ) : (
                <>
                  <AlertIcon size={16} aria-hidden="true" data-testid="permissions-mode-status-icon-x" />
                  <span>bypass allowed</span>
                </>
              )}
            </div>
          </div>
        )}
      </div>
    </Stack>
  )
}
