import {Button, Dialog} from '@primer/react'
import type {SuggestedOrg, ConfirmationDialogType} from '../types'

interface OrgConfirmationDialogProps {
  isOpen: boolean
  type: ConfirmationDialogType
  newOrg?: SuggestedOrg
  currentOrgName?: string
  onConfirm: () => void
  onCancel: () => void
}

export function OrgConfirmationDialog({
  isOpen,
  type,
  newOrg,
  currentOrgName,
  onConfirm,
  onCancel,
}: OrgConfirmationDialogProps) {
  if (!isOpen) return null

  const getTitle = () => {
    switch (type) {
      case 'change':
        return 'Change target organization'
      case 'set':
        return 'Set target organization'
      case 'unset':
        return 'Unset target organization'
      default:
        return 'Confirm Action'
    }
  }

  const getBodyContent = () => {
    switch (type) {
      case 'change':
        return (
          <>
            <p>
              Changing the target organization from <strong>{currentOrgName}</strong> to <strong>{newOrg?.name}</strong>{' '}
              will remove all custom agents and copilot client settings configured for your enterprise.
            </p>
            <p>
              Setting the target organization to <strong>{newOrg?.name}</strong> will enable custom agents and copilot
              client settings on source repository{' '}
              <span className="fgColor-muted" style={{wordBreak: 'break-word'}}>
                {newOrg?.name}/.github-private
              </span>{' '}
              to all users in your enterprise.
            </p>
          </>
        )
      case 'set':
        return (
          <>
            <p>
              Selecting the target organization will add all custom agents and copilot client settings configured for
              your enterprise.
            </p>
            <p>
              Setting the target organization to <strong>{newOrg?.name}</strong> will enable custom agents and copilot
              client settings on source repository{' '}
              <span className="fgColor-muted" style={{wordBreak: 'break-word'}}>
                {newOrg?.name}/.github-private
              </span>{' '}
              to all users in your enterprise.
            </p>
          </>
        )
      case 'unset':
        return (
          <>
            <p>
              Removing the target organization <strong>{currentOrgName}</strong> will remove all custom agents and
              copilot client settings configured for your enterprise.
            </p>
          </>
        )
      default:
        return <p>Are you sure you want to proceed?</p>
    }
  }

  const getButtonText = () => {
    switch (type) {
      case 'change':
        return 'Change Organization'
      case 'set':
        return 'Set Organization'
      case 'unset':
        return 'Confirm'
      default:
        return 'Confirm'
    }
  }

  return (
    <Dialog onClose={onCancel} title={getTitle()} width="medium">
      <Dialog.Body>
        <div style={{wordBreak: 'break-word', overflowWrap: 'break-word'}}>{getBodyContent()}</div>
      </Dialog.Body>
      <Dialog.Footer>
        <Button onClick={onCancel}>Back</Button>
        <Button variant={type === 'unset' ? 'danger' : 'primary'} onClick={onConfirm}>
          {getButtonText()}
        </Button>
      </Dialog.Footer>
    </Dialog>
  )
}
