import {mainQuery} from '@github-ui/react-core/future/main-query'
import {copilotAgentPlaneAppBuilder} from '../config/app-builder'

export type Agent = {
  name: string
  enabled?: boolean
  policy?: string
}

export type SourceOrg = {
  id: number | null
  name: string | null
  avatar_url: string | null
}

export type CustomAgent = {
  name: string
  repo_owner: string
  repo_name: string
  url: string
}

export type ThirdPartyAgent = {
  name: string
  enabled: boolean
  doc_url: string
  toggle_url: string
  integration: {
    avatar_url: string
  }
}

export type EnterpriseManagedClientSettings = {
  source_repo_url: string
  display_name_with_owner: string
  settings?: Record<string, unknown>
}

export type AgentsResponse = {
  agents: Agent[]
  third_party_agents?: ThirdPartyAgent[]
  source_org: SourceOrg
  can_write: boolean
  can_admin: boolean
  can_view_audit_logs: boolean
  can_view_third_party_agents?: boolean
  third_party_agents_enabled: boolean
  enterprise_managed_client_settings?: EnterpriseManagedClientSettings | null
}

export const agentsRoute = copilotAgentPlaneAppBuilder.createQueryRouteConfig('agentsRoute', {
  path: '/enterprises/:slug/ai-controls/agents',
  queries: [mainQuery<AgentsResponse>()],
})
