import type {ReactElement} from 'react'
import type {BaseOrganization} from '@github-ui/org-selector'

export const Status = {
  enabled: 'Enabled',
  disabled: 'Disabled',
} as const
export type Status = (typeof Status)[keyof typeof Status]

export type Agent = {
  name: string
  status: Status
}

export type CustomAgent = Agent & {
  organization: {
    name: string
  }
  repository: {
    name: string
  }
}

export type ExtendedBaseOrganization = BaseOrganization & {
  id: number
}

export type Enforcement = 'enabled' | 'disabled' | 'evaluate'

export type Ruleset = {
  id: number
  name: string
  url: string
  enforcement: Enforcement
}

export type AppPayload = {
  paths: {
    showRuleset: string
    createRuleset: string
  }
}

export const BannerType = {
  Success: 'success',
  Critical: 'critical',
} as const
export type BannerType = (typeof BannerType)[keyof typeof BannerType]
export type Banner = {
  type: BannerType
  title: string
  message: ReactElement | string
}

export type SuggestedOrg = {id: number; name: string; primaryAvatarUrl: string}
export type SuggestedOrgs = SuggestedOrg[]
export type ConfirmationDialogType = 'change' | 'unset' | 'set'
